/**
 * Hash chain for append-only records (GV-3). Each record carries a link: its position, the hash of the record before
 * it, and its own hash over (position, previous hash, canonical content). Changing, removing or reordering a record
 * breaks every link after it, so the damage is found by reading the log, without a separate index.
 *
 * What a chain cannot show by itself: records removed from the END leave a shorter chain that is still consistent.
 * A log with a defined last record (a flight's `session_end`) reports whether it is closed; anything stronger needs
 * a copy of the head hash kept somewhere else (the signed audit export, GV-2).
 *
 * This is tamper evidence, not tamper proofing: someone who can rewrite the whole file can recompute every hash.
 */
import { createHash } from "node:crypto";

export interface ChainLink {
  /** Position in the log, from 0. */
  seq: number;
  /** `hash` of the previous record; CHAIN_GENESIS for the first. */
  prev: string;
  /** SHA-256 over `${seq}\n${prev}\n${canonicalJson(record without its chain)}`, hex. */
  hash: string;
}

export const CHAIN_GENESIS = "0".repeat(64);
const HEX64 = /^[0-9a-f]{64}$/;

/**
 * JSON with object keys sorted at every depth, so a record hashes the same after it has been written and parsed
 * again. Follows JSON.stringify for everything else (undefined members dropped, non-finite numbers as null).
 */
export function canonicalJson(value: unknown): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value) ?? "null";
  if (Array.isArray(value)) return `[${value.map((item) => (item === undefined ? "null" : canonicalJson(item))).join(",")}]`;
  const toJson = (value as { toJSON?: () => unknown }).toJSON;
  if (typeof toJson === "function") return canonicalJson(toJson.call(value));
  const members: string[] = [];
  for (const key of Object.keys(value as Record<string, unknown>).sort()) {
    const member = (value as Record<string, unknown>)[key];
    if (member === undefined || typeof member === "function" || typeof member === "symbol") continue;
    members.push(`${JSON.stringify(key)}:${canonicalJson(member)}`);
  }
  return `{${members.join(",")}}`;
}

function linkHash(seq: number, prev: string, content: unknown): string {
  return createHash("sha256").update(`${seq}\n${prev}\n${canonicalJson(content)}`, "utf8").digest("hex");
}

function withoutChain(record: object): Record<string, unknown> {
  const { chain: _chain, ...content } = record as Record<string, unknown>;
  return content;
}

/** The record with its link to `previous` (the link of the record before it; undefined for the first). */
export function linkRecord<T extends object>(record: T, previous: ChainLink | undefined): T & { chain: ChainLink } {
  const seq = previous ? previous.seq + 1 : 0;
  const prev = previous ? previous.hash : CHAIN_GENESIS;
  return { ...record, chain: { seq, prev, hash: linkHash(seq, prev, withoutChain(record)) } };
}

export type ChainProblem =
  /** The record's content does not match its hash: it was changed after it was written. */
  | "edited"
  /** The record does not follow the one before it: something was removed, inserted or reordered here. */
  | "out_of_order"
  /** A record without a link inside a chained log, or a line that is not a record at all. */
  | "unlinked";

export type ChainVerdict =
  /** Every record links to the one before it. `head` is the last link (absent for an empty log). */
  | { status: "intact"; records: number; head?: ChainLink }
  /** No record carries a link: written before chaining existed. Nothing can be said about its integrity. */
  | { status: "unchained"; records: number }
  /** The first record that fails, by position in the input. Records before it verified; nothing after it was trusted. */
  | { status: "broken"; records: number; at: number; problem: ChainProblem; detail: string };

function readLink(record: unknown): ChainLink | undefined {
  const chain = record && typeof record === "object" ? (record as { chain?: unknown }).chain : undefined;
  if (!chain || typeof chain !== "object") return undefined;
  const { seq, prev, hash } = chain as Record<string, unknown>;
  if (!Number.isSafeInteger(seq) || (seq as number) < 0 || typeof prev !== "string" || typeof hash !== "string") return undefined;
  if (!HEX64.test(prev) || !HEX64.test(hash)) return undefined;
  return { seq: seq as number, prev, hash };
}

function hasChainField(record: unknown): boolean {
  return record !== null && typeof record === "object" && Object.prototype.hasOwnProperty.call(record, "chain");
}

/**
 * Check a log read back from disk. `records` are the parsed records in file order; pass `null` for a line that could
 * not be parsed, so it is reported at its position instead of being skipped.
 */
export function verifyChain(records: ReadonlyArray<unknown>): ChainVerdict {
  const total = records.length;
  if (total === 0) return { status: "intact", records: 0 };
  if (records.every((record) => record !== null && readLink(record) === undefined && !hasChainField(record))) {
    return { status: "unchained", records: total };
  }
  let previous: ChainLink | undefined;
  for (let at = 0; at < total; at++) {
    const record = records[at];
    const link = readLink(record);
    if (!link) {
      const detail = record === null
        ? "this line is not a readable record"
        : hasChainField(record)
          ? "this record has a malformed chain link"
          : "this record has no chain link, but the log is chained";
      return { status: "broken", records: total, at, problem: "unlinked", detail };
    }
    const expectedSeq = previous ? previous.seq + 1 : 0;
    const expectedPrev = previous ? previous.hash : CHAIN_GENESIS;
    if (link.seq !== expectedSeq || link.prev !== expectedPrev) {
      const detail = link.seq !== expectedSeq
        ? `expected record ${expectedSeq} here, found record ${link.seq}`
        : `record ${link.seq} does not follow the record before it`;
      return { status: "broken", records: total, at, problem: "out_of_order", detail };
    }
    if (linkHash(link.seq, link.prev, withoutChain(record as object)) !== link.hash) {
      return { status: "broken", records: total, at, problem: "edited", detail: `record ${link.seq} was changed after it was written` };
    }
    previous = link;
  }
  return { status: "intact", records: total, head: previous };
}

/** One line an operator can read. */
export function describeChain(verdict: ChainVerdict): string {
  switch (verdict.status) {
    case "intact":
      return verdict.records === 0 ? "empty" : `chain intact (${verdict.records} record${verdict.records === 1 ? "" : "s"})`;
    case "unchained":
      return `not chained (${verdict.records} record${verdict.records === 1 ? "" : "s"} written before hash chaining; integrity cannot be checked)`;
    case "broken":
      return `CHAIN BROKEN at position ${verdict.at + 1} of ${verdict.records}: ${verdict.detail}`;
  }
}
// What the generators of the two command-result schemas share (gen_run_result_schema.mjs for `nexus run --json`,
// gen_verify_result_schema.mjs for `nexus verify --json`): one root type and one version constant in one contract
// source, written with the `SchemaBuilder` of gen_protocol_schema.mjs, and a ledger keyed by `schema_version`.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { API, SymbolFlags } from "typescript/unstable/sync";
import { SchemaBuilder, sha256, sortKeys } from "./gen_protocol_schema.mjs";

export const cli = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
export const repo = path.resolve(cli, "..");

/**
 * The schema text for `rootType` as `source` (relative to cli/) declares it now, and the value of `versionConst`.
 * `script` names the generator in errors; `title(version)` and `description` are the schema's annotations.
 */
export function generateResultSchema({ script, source, rootType, versionConst, title, description }) {
  const api = new API({ cwd: cli });
  try {
    const snapshot = api.updateSnapshot({ openProjects: [path.join(cli, "tsconfig.json")] });
    const project = snapshot.getProjects()[0];
    if (!project) throw new Error(`${script}: cli/tsconfig.json did not load as a project`);
    const checker = project.checker;
    const sourceAt = { document: path.join(cli, source), position: 0 };
    const versionSymbol = checker.resolveName(versionConst, SymbolFlags.Value, sourceAt);
    const version = versionSymbol && checker.getTypeOfSymbol(versionSymbol)?.value;
    if (!Number.isInteger(version)) throw new Error(`${script}: ${versionConst} is not an integer literal in ${source}`);
    const rootSymbol = checker.resolveName(rootType, SymbolFlags.TypeAlias, sourceAt);
    if (!rootSymbol) throw new Error(`${script}: ${rootType} is not declared in ${source}`);
    const root = checker.getDeclaredTypeOfSymbol(rootSymbol);
    if (root.isErrorType()) throw new Error(`${script}: ${rootType} did not resolve`);

    const builder = new SchemaBuilder(checker);
    const rootSchema = builder.schemaOf(root, rootType);
    const schema = {
      $schema: "https://json-schema.org/draft/2020-12/schema",
      title: title(version),
      description,
      ...rootSchema,
      $defs: sortKeys(builder.defs),
    };
    return { version, text: `${JSON.stringify(schema, null, 2)}\n` };
  } finally {
    api.close();
  }
}

/**
 * The version-decision rule (the same as the protocol ledger's, with the key `schema_version`): the newest ledger entry
 * must name the current schema version and the hash of the checked-in schema. Returns what is wrong, or undefined.
 */
export function resultLedgerProblem(schemaText, ledger, version, versionConst) {
  if (!Array.isArray(ledger) || ledger.length === 0) return "the ledger has no entries";
  const last = ledger[ledger.length - 1];
  if (last.schema_version !== version) return `the newest ledger entry is for schema_version ${last.schema_version}, but ${versionConst} is ${version}`;
  const hash = sha256(schemaText);
  if (last.schemaSha256 !== hash) return `the newest ledger entry records schema ${last.schemaSha256}, but the schema is ${hash}: add an entry that records the version decision`;
  return undefined;
}

/** The command line of a generator: write the schema, or with `--check` exit 1 when the schema or its ledger is stale. */
export function resultSchemaMain({ script, generate, schemaFile, ledgerFile, ledgerProblem }) {
  const { version, text } = generate();
  const file = schemaFile(version);
  const shown = path.relative(repo, file).split(path.sep).join("/");
  const ledgerShown = path.relative(repo, ledgerFile).split(path.sep).join("/");
  if (process.argv.includes("--check")) {
    const current = fs.existsSync(file) ? fs.readFileSync(file, "utf8") : undefined;
    if (current !== text) {
      console.error(`${shown} is ${current === undefined ? "missing" : "out of date"}: run \`node cli/scripts/${script}.mjs\`, then record the version decision in ${ledgerShown}`);
      process.exit(1);
    }
    const problem = ledgerProblem(current, fs.existsSync(ledgerFile) ? JSON.parse(fs.readFileSync(ledgerFile, "utf8")) : [], version);
    if (problem) {
      console.error(`${ledgerShown}: ${problem}`);
      process.exit(1);
    }
    console.log(`${shown} is current`);
  } else {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, text);
    console.log(`wrote ${shown} (sha256 ${sha256(text)})`);
  }
}
// Generates the JSON Schema (draft 2020-12) of the document `nexus verify --json` prints (the same document
// `--receipt <file>` writes), from the type `VerifyJsonOutput` in src/verify_contract.ts, with the `SchemaBuilder` of
// gen_protocol_schema.mjs (see docs/protocol/README.md): deterministic output, compared byte for byte.
//
//   node scripts/gen_verify_result_schema.mjs           write docs/protocol/verify-result-v<N>.schema.json
//   node scripts/gen_verify_result_schema.mjs --check   exit 1 when the checked-in schema or the version ledger is stale
import path from "node:path";
import { fileURLToPath } from "node:url";
import { generateResultSchema, repo, resultLedgerProblem, resultSchemaMain } from "./result_schema.mjs";

const SCRIPT = "gen_verify_result_schema";

export const VERIFY_RESULT_LEDGER_FILE = path.join(repo, "docs", "protocol", "VERIFY_RESULT_VERSIONS.json");
export const verifyResultSchemaFile = (version) => path.join(repo, "docs", "protocol", `verify-result-v${version}.schema.json`);

/** The schema text for `VerifyJsonOutput` as src/verify_contract.ts declares it now, and its `VERIFY_RESULT_SCHEMA_VERSION`. */
export function generateVerifyResultSchema() {
  return generateResultSchema({
    script: SCRIPT,
    source: "src/verify_contract.ts",
    rootType: "VerifyJsonOutput",
    versionConst: "VERIFY_RESULT_SCHEMA_VERSION",
    title: (version) => `nexus verify --json output v${version}`,
    description:
      "Generated from VerifyJsonOutput in cli/src/verify_contract.ts by cli/scripts/gen_verify_result_schema.mjs. Do not edit by hand. The one JSON document `nexus verify --json` writes to stdout and `--receipt` writes to a file; `schema_version` is its first member.",
  });
}

/** The version-decision rule for the verify-result ledger (see resultLedgerProblem). Returns what is wrong, or undefined. */
export function verifyResultLedgerProblem(schemaText, ledger, version) {
  return resultLedgerProblem(schemaText, ledger, version, "VERIFY_RESULT_SCHEMA_VERSION");
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  resultSchemaMain({ script: SCRIPT, generate: generateVerifyResultSchema, schemaFile: verifyResultSchemaFile, ledgerFile: VERIFY_RESULT_LEDGER_FILE, ledgerProblem: verifyResultLedgerProblem });
}
