/**
 * PF-2: the machine contract of `nexus run`: the JSON document `--json` prints, the process exit codes, and the task
 * input read from `--input-json` or stdin. The published schema (docs/protocol/run-result-v1.schema.json) is generated
 * from the types here by scripts/gen_run_result_schema.mjs; docs/USER_MANUAL.md documents the exit codes from the table
 * below, and test/run_json_contract.test.ts fails when either falls behind.
 */
import fs from "node:fs";
import type { TaskExecutionResult } from "./core/app.js";
import type { EngineeringOutcome, ExecutionState } from "./core/turn.js";
import type { UsageTotals } from "./usage.js";

/**
 * Version of the document `nexus run --json` prints. Adding an optional member keeps the version; removing or renaming
 * a member, or changing a member's type or meaning, bumps it. Every change is recorded in
 * docs/protocol/RUN_RESULT_VERSIONS.json.
 */
export const RUN_RESULT_SCHEMA_VERSION = 1;

/** Printed when the task ran to an ending (whatever the ending): the task result with the contract version first. */
export interface RunJsonResult extends TaskExecutionResult {
  /** Version of this document's schema. Always the first member. */
  schema_version: typeof RUN_RESULT_SCHEMA_VERSION;
  /** Cloud provider usage of this process; present only when at least one cloud request was made. */
  cloudUsage?: UsageTotals;
}

/**
 * Printed instead of a result when the run threw before producing one (for example `--resume` of a task that does not
 * exist). It has no `turn` and no `exitCode`: read the process exit code.
 */
export interface RunJsonError {
  /** Version of this document's schema. Always the first member. */
  schema_version: typeof RUN_RESULT_SCHEMA_VERSION;
  taskId: string;
  success: false;
  status: "failed";
  prompt: string;
  output: string;
  plan: TaskExecutionResult["plan"];
  milestones: TaskExecutionResult["milestones"];
  validationReceipts: TaskExecutionResult["validationReceipts"];
  tokenStats: TaskExecutionResult["tokenStats"];
  durationMs: number;
  /** Why the run failed (redacted). */
  error: string;
}

/** The one JSON document `nexus run --json` writes to stdout. A result has `turn`; an error document does not. */
export type RunJsonOutput = RunJsonResult | RunJsonError;

/** The document for a finished task: `schema_version` first, every result member unchanged, `cloudUsage` when cloud requests were made. */
export function runJsonResult(result: TaskExecutionResult, cloud?: UsageTotals): RunJsonResult {
  return { schema_version: RUN_RESULT_SCHEMA_VERSION, ...result, ...(cloud?.requests ? { cloudUsage: cloud } : {}) };
}

export interface RunExitCode {
  code: number;
  name: string;
  when: string;
}

/**
 * Every exit code of `nexus run`, one row per condition. A code can appear in several rows (2 does): the exit code
 * alone does not tell those conditions apart, the JSON document does. The "Exit codes" table in docs/USER_MANUAL.md is
 * this table.
 */
export const RUN_EXIT_CODES = [
  { code: 0, name: "ok", when: "The task completed and its changes were verified (`VERIFIED`), or it changed nothing that needs verifying (`NOT_REQUIRED`)." },
  { code: 1, name: "failed", when: "Any other ending: the task failed, was blocked (a question for the operator, a capacity or convergence stop), reached a limit, or completed without establishing a result; or the run threw an error." },
  { code: 1, name: "missing_prompt", when: "No task was given as an argument and `--resume` was not used (with a terminal on stdin and no `--input-json`)." },
  { code: 1, name: "option_parse", when: "The command line could not be parsed: an unknown option or an option without its value (the option parser exits before the command runs)." },
  { code: 2, name: "unverified", when: "The task completed but nothing verifies the change (`UNVERIFIED`), or the tests passed without covering it (`REGRESSION_FREE`)." },
  { code: 2, name: "usage", when: "A usage error before the run started: an invalid option value or combination, or an invalid, oversized or empty `--input-json` or stdin task." },
  { code: 2, name: "resume_unavailable", when: "`--resume` found no task in the workspace, or `--fork-session` could not make the copy." },
  { code: 2, name: "task_not_found", when: "The task named by `--resume <id>` has no saved state." },
  { code: 130, name: "interrupted", when: "The task was interrupted (SIGINT). A second SIGINT exits at once with this code and may leave no JSON document." },
] as const satisfies readonly RunExitCode[];

export type RunExitName = (typeof RUN_EXIT_CODES)[number]["name"];

export function runExitCode(name: RunExitName): number {
  return RUN_EXIT_CODES.find((row) => row.name === name)!.code;
}

/** The exit-code row of a turn that did not complete, by execution state. A new state does not compile until its row is decided. */
export const RUN_EXIT_FOR_EXECUTION: Record<Exclude<ExecutionState, "COMPLETED">, RunExitName> = {
  INTERRUPTED: "interrupted",
  FAILED: "failed",
  BLOCKED: "failed",
  LIMIT_REACHED: "failed",
};

/** The exit-code row of a completed turn, by outcome. A new outcome does not compile until its row is decided. */
export const RUN_EXIT_FOR_COMPLETED_OUTCOME: Record<EngineeringOutcome, RunExitName> = {
  VERIFIED: "ok",
  NOT_REQUIRED: "ok",
  UNVERIFIED: "unverified",
  REGRESSION_FREE: "unverified",
  NOT_ESTABLISHED: "failed",
};

/** The table's row for a turn. `exitCodeForTurn` (core/turn.ts) computes the code itself; a test pins the two together. */
export function runExitNameForTurn(turn: { execution: ExecutionState; outcome: EngineeringOutcome }): RunExitName {
  return turn.execution === "COMPLETED" ? RUN_EXIT_FOR_COMPLETED_OUTCOME[turn.outcome] : RUN_EXIT_FOR_EXECUTION[turn.execution];
}

/** Version of the `--input-json` document. */
export const RUN_INPUT_SCHEMA_VERSION = 1;
/** Largest task input accepted from `--input-json` or stdin, in bytes. A larger input is rejected, never truncated. */
export const RUN_INPUT_MAX_BYTES = 1024 * 1024;

/** Reads a whole stream as UTF-8 text, refusing more than RUN_INPUT_MAX_BYTES. */
async function readBounded(stream: AsyncIterable<Buffer | string>, what: string): Promise<string> {
  const chunks: Buffer[] = [];
  let bytes = 0;
  for await (const chunk of stream) {
    const piece = typeof chunk === "string" ? Buffer.from(chunk) : chunk;
    bytes += piece.length;
    if (bytes > RUN_INPUT_MAX_BYTES) throw new Error(`${what} is larger than ${RUN_INPUT_MAX_BYTES} bytes`);
    chunks.push(piece);
  }
  try {
    return new TextDecoder("utf-8", { fatal: true }).decode(Buffer.concat(chunks));
  } catch {
    throw new Error(`${what} is not valid UTF-8`);
  }
}

/**
 * The task of an `--input-json` document: `{ "schema_version": 1, "task": "<text>" }`. Only `task` is read. Every other
 * member is ignored, so the document cannot set the approval mode, sandbox, endpoint, credentials or workspace: those
 * stay with the command line and the operator's configuration.
 */
export function parseRunInput(text: string): string {
  let doc: unknown;
  try {
    doc = JSON.parse(text);
  } catch {
    throw new Error("--input-json: the input is not valid JSON");
  }
  if (doc === null || typeof doc !== "object" || Array.isArray(doc)) throw new Error("--input-json: the input must be a JSON object");
  const { schema_version: version, task } = doc as Record<string, unknown>;
  if (version !== RUN_INPUT_SCHEMA_VERSION) {
    throw new Error(`--input-json: ${version === undefined ? "schema_version is missing" : `unsupported schema_version ${JSON.stringify(version)}`} (this nexus reads schema_version ${RUN_INPUT_SCHEMA_VERSION})`);
  }
  if (typeof task !== "string" || !task.trim()) throw new Error('--input-json: "task" must be a non-empty string');
  return task.trim();
}

export interface RunTaskSource {
  /** The task given as command-line arguments, joined and trimmed; empty when none. */
  prompt: string;
  /** The value of `--input-json`: a file path, or `-` for stdin. */
  inputJson?: string;
  /** `--resume` or `--fork-session` is in effect: a missing task is allowed and stdin is not read for one. */
  resuming: boolean;
  stdin: AsyncIterable<Buffer | string> & { isTTY?: boolean };
}

/**
 * The task text of a run. An argument wins when it is the only source; `--input-json` supplies it from a document;
 * otherwise, when not resuming and stdin is not a terminal, stdin is the task as plain text. Throws a usage error
 * (exit code `usage`) for a conflict or an invalid input. Returns "" when no source applies (a terminal on stdin, or a
 * resume): the caller keeps its existing handling of a missing task.
 */
export async function resolveRunTask(source: RunTaskSource): Promise<string> {
  if (source.inputJson !== undefined) {
    if (source.prompt) throw new Error("give the task either as an argument or with --input-json, not both");
    if (source.inputJson === "-") return parseRunInput(await readBounded(source.stdin, "--input-json: the input"));
    let text: string;
    try {
      text = await readBounded(fs.createReadStream(source.inputJson), "--input-json: the input");
    } catch (err: any) {
      if (!err?.code) throw err;
      throw new Error(`--input-json: cannot read ${source.inputJson} (${err.code})`);
    }
    return parseRunInput(text);
  }
  if (source.prompt || source.resuming || source.stdin.isTTY) return source.prompt;
  const task = (await readBounded(source.stdin, "the task on stdin")).trim();
  if (!task) throw new Error("no task: stdin was empty (give the task as an argument, on stdin, or with --input-json)");
  return task;
}
/**
 * VR-1: the machine contract of `nexus verify`: the verdicts, the process exit codes and the JSON document `--json`
 * prints (the same document `--receipt <file>` writes). docs/USER_MANUAL.md documents the exit codes from the table
 * below and test/verify_command.test.ts fails when the manual falls behind. The published schema
 * (docs/protocol/verify-result-v1.schema.json) is generated from the types here by scripts/gen_verify_result_schema.mjs,
 * so they are plain data (no functions, no index signatures); test/verify_schema.test.ts fails when it falls behind.
 */
import type { EngineeringOutcome, TypecheckEvidence, VerificationEvidence } from "./core/turn.js";
import type { TypecheckBaselineRecord } from "./core/typecheck_evidence.js";
import type { EvidenceOutcomeReason } from "./core/verification_outcome.js";
import type { VerificationClass, VerificationMode } from "./security.js";
import type { TypecheckMode } from "./tester.js";

/**
 * Version of the document `nexus verify --json` prints. Adding an optional member keeps the version; removing or
 * renaming a member, or changing a member's type or meaning, bumps it. Every change is recorded in
 * docs/protocol/VERIFY_RESULT_VERSIONS.json.
 */
export const VERIFY_RESULT_SCHEMA_VERSION = 1;

/**
 * VERIFIED: evidence independent of the change shows it. REGRESSION_FREE: the tests pass, which shows only that nothing
 * they cover broke. UNVERIFIED: nothing was established (see `outcome` and `reason`). BLOCKED: a person must decide
 * before anything is run or concluded.
 */
export type VerifyVerdict = "VERIFIED" | "REGRESSION_FREE" | "UNVERIFIED" | "BLOCKED";

/** Why the verdict is not VERIFIED: the outcome ladder's reasons, and the ones only `nexus verify` gives. */
export type VerifyReason =
  | EvidenceOutcomeReason
  /** Base and head are the same tree. */
  | "NOTHING_TO_VERIFY"
  /** The head changed the files that define the verifier, so the verifier was not run on the head. */
  | "VERIFIER_DEFINITION_CHANGED"
  /** The verifier is an inline program whose definition cannot be captured, so it was not run on the head. */
  | "VERIFIER_DEFINITION_NOT_CAPTURED"
  /** An enforced type-check failed on the head: an error in a changed file, or one the base did not have. */
  | "TYPECHECK_FAILED"
  /** An enforced type-check did not finish within the deadline. */
  | "TYPECHECK_TIMED_OUT"
  /** An enforced type-check could not be run: its tool is not installed, or its configuration is one this checker cannot run. */
  | "TYPECHECK_UNAVAILABLE"
  /** Type-checking is enforced and a project of the base tree has no counterpart in the head, so no evidence exists for it. */
  | "TYPECHECK_NOT_RUN"
  /** The change edits verification files (or weakens a test) and the edit was not approved, or the base's policy refuses such edits. */
  | "VERIFICATION_EDIT_BLOCKED"
  /** Not every changed file could be classified, so the guard's findings are not the whole picture. */
  | "GUARD_INCOMPLETE"
  /** A verifier discovered in the repository needs the operator's approval. */
  | "VERIFIER_NOT_APPROVED"
  /** Git was refused in the checkout (a planted or rewritten `.git`). */
  | "UNTRUSTED_CHECKOUT"
  /** A tree is larger than the limits, or reading it took longer than allowed. */
  | "TREE_LIMIT_EXCEEDED"
  /** A tree holds something that is not materialised (a submodule). */
  | "UNSUPPORTED_TREE"
  /** `nexus verify` itself failed; nothing was established. */
  | "INTERNAL_ERROR";

export interface VerifyExitCode {
  code: number;
  name: string;
  when: string;
}

/**
 * Every exit code of `nexus verify`, one row per condition (the same row shape as RUN_EXIT_CODES). A code can appear in
 * several rows: the exit code alone does not tell those conditions apart, the JSON document does. The "Exit codes"
 * table in docs/USER_MANUAL.md is this table. Unlike `nexus run`, code 3 exists (a person must decide) and an empty
 * change is not 0 (the caller chose the base).
 */
export const VERIFY_EXIT_CODES = [
  { code: 0, name: "verified", when: "`VERIFIED`: the change is shown by evidence independent of it." },
  { code: 1, name: "failed", when: "`UNVERIFIED` with outcome `NOT_ESTABLISHED`: the verifier failed or timed out on the head, an enforced type-check failed, timed out or could not be run, or the head changed the verifier's own definition so it was not run." },
  { code: 1, name: "error", when: "`UNVERIFIED` with reason `INTERNAL_ERROR`: `nexus verify` itself could not finish, so nothing was established." },
  { code: 1, name: "option_parse", when: "The command line could not be parsed: an unknown option or an option without its value (the option parser exits before the command runs; no JSON document)." },
  { code: 2, name: "unverified", when: "`REGRESSION_FREE` (the tests pass without showing the change), or `UNVERIFIED` because there is no verifier, no test executed, base and head are the same tree, or an enforced type-check project of the base has no counterpart in the head." },
  { code: 2, name: "usage", when: "A usage error: not a Git working tree, a base or head that does not name a commit, or an invalid option value or combination." },
  { code: 3, name: "blocked", when: "`BLOCKED`: a person must decide. The discovered verifier is not approved, the change edits verification files or weakens a test without approval, the changed files could not all be classified, the checkout is not trusted, or a tree exceeds the limits or holds a submodule." },
  { code: 130, name: "interrupted", when: "Interrupted (SIGINT or SIGTERM). The signal is acted on when the running verifier process ends; a second signal exits at once and may leave no JSON document." },
] as const satisfies readonly VerifyExitCode[];

export type VerifyExitName = (typeof VERIFY_EXIT_CODES)[number]["name"];

export function verifyExitCode(name: VerifyExitName): number {
  return VERIFY_EXIT_CODES.find((row) => row.name === name)!.code;
}

/** The verdict and exit-code row of every reason. A new reason does not compile until both are decided. */
export const VERIFY_REASONS: Record<VerifyReason, { verdict: Exclude<VerifyVerdict, "VERIFIED">; exit: VerifyExitName }> = {
  REGRESSION_FREE: { verdict: "REGRESSION_FREE", exit: "unverified" },
  NO_APPLICABLE_VERIFIER: { verdict: "UNVERIFIED", exit: "unverified" },
  NO_TESTS_EXECUTED: { verdict: "UNVERIFIED", exit: "unverified" },
  VERIFICATION_NOT_RUN: { verdict: "UNVERIFIED", exit: "unverified" },
  NOTHING_TO_VERIFY: { verdict: "UNVERIFIED", exit: "unverified" },
  TYPECHECK_NOT_RUN: { verdict: "UNVERIFIED", exit: "unverified" },
  TYPECHECK_FAILED: { verdict: "UNVERIFIED", exit: "failed" },
  TYPECHECK_TIMED_OUT: { verdict: "UNVERIFIED", exit: "failed" },
  TYPECHECK_UNAVAILABLE: { verdict: "UNVERIFIED", exit: "failed" },
  VERIFIER_FAILED: { verdict: "UNVERIFIED", exit: "failed" },
  VERIFIER_TIMED_OUT: { verdict: "UNVERIFIED", exit: "failed" },
  VERIFIER_DEFINITION_CHANGED: { verdict: "UNVERIFIED", exit: "failed" },
  VERIFIER_DEFINITION_NOT_CAPTURED: { verdict: "UNVERIFIED", exit: "failed" },
  INTERNAL_ERROR: { verdict: "UNVERIFIED", exit: "error" },
  VERIFIER_NOT_APPROVED: { verdict: "BLOCKED", exit: "blocked" },
  VERIFICATION_EDIT_BLOCKED: { verdict: "BLOCKED", exit: "blocked" },
  GUARD_INCOMPLETE: { verdict: "BLOCKED", exit: "blocked" },
  UNTRUSTED_CHECKOUT: { verdict: "BLOCKED", exit: "blocked" },
  TREE_LIMIT_EXCEEDED: { verdict: "BLOCKED", exit: "blocked" },
  UNSUPPORTED_TREE: { verdict: "BLOCKED", exit: "blocked" },
};

/** The verdict for a reason; no reason is VERIFIED. */
export function verifyVerdictFor(reason: VerifyReason | undefined): VerifyVerdict {
  return reason === undefined ? "VERIFIED" : VERIFY_REASONS[reason].verdict;
}

/** The exit-code row for a reason; no reason is VERIFIED. */
export function verifyExitNameFor(reason: VerifyReason | undefined): VerifyExitName {
  return reason === undefined ? "verified" : VERIFY_REASONS[reason].exit;
}

/** One side of the comparison. */
export interface VerifyTreeRef {
  /** What the operator named: a ref, or "(working tree)". */
  ref: string;
  /** The commit; null for the working tree, which has none. */
  commit: string | null;
  /** The Git tree that was materialised and verified. For the working tree: tracked and untracked files that are not ignored, as `git add -A` would stage them (Nexus's own `.nexus` state left out). */
  tree: string;
  workingTree: boolean;
}

export interface VerifyVerifierRecord {
  command: string;
  /** `configured`: the operator's `--verifier`. `discovered`: selected from the files of the base tree. */
  source: "configured" | "discovered";
  /** The base-tree file that justifies a discovered verifier, or "configured". */
  evidence: string;
  /** sha256 of the command and the script body it resolves to in the base tree. */
/**
 * GV-3: the flight recorder and the verification-configuration attempt log are hash-chained, so a record that was
 * changed, removed or reordered is found when the log is read. What a chain cannot show (records cut from the end)
 * is asserted too, so the limit stays stated rather than assumed away.
 */
import { after, describe, test } from "node:test";
import assert from "node:assert/strict";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { CHAIN_GENESIS, canonicalJson, describeChain, linkRecord, verifyChain, type ChainLink } from "../src/core/hash_chain.js";
import { FlightPlayer, FlightRecorder } from "../src/flight.js";
import { SecurityManager } from "../src/security.js";

const tempDirs: string[] = [];
after(() => {
  for (const dir of tempDirs) fs.rmSync(dir, { recursive: true, force: true });
});
function workspace(): string {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-gv3-"));
  tempDirs.push(dir);
  return dir;
}

function chainOf(contents: object[]): Array<object & { chain: ChainLink }> {
  const out: Array<object & { chain: ChainLink }> = [];
  for (const content of contents) out.push(linkRecord(content, out[out.length - 1]?.chain));
  return out;
}
/** As the records come back from disk. */
const reread = <T>(records: T[]): T[] => records.map((r) => JSON.parse(JSON.stringify(r)));

describe("canonical JSON", () => {
  test("key order does not change the text; nesting, arrays and dropped members follow JSON.stringify", () => {
    assert.equal(canonicalJson({ b: 1, a: { d: [3, { z: 1, y: 2 }], c: null } }), '{"a":{"c":null,"d":[3,{"y":2,"z":1}]},"b":1}');
    assert.equal(canonicalJson({ a: 1, b: undefined, c: () => 1 }), '{"a":1}');
    assert.equal(canonicalJson([undefined, 1]), "[null,1]");
    assert.equal(canonicalJson({ when: new Date(0) }), '{"when":"1970-01-01T00:00:00.000Z"}');
    assert.equal(canonicalJson("x\n "), JSON.stringify("x\n "));
  });
});

describe("chain", () => {
  const base = [{ type: "a", payload: { n: 1 } }, { type: "b", payload: { text: "héllo ✓" } }, { type: "c", payload: {} }, { type: "d", payload: { list: [1, 2] } }];

  test("a log read back as written is intact, and the first link starts from the genesis value", () => {
    const records = reread(chainOf(base));
    assert.equal((records[0] as any).chain.prev, CHAIN_GENESIS);
    assert.deepEqual((records as any[]).map((r) => r.chain.seq), [0, 1, 2, 3]);
    const verdict = verifyChain(records);
    assert.equal(verdict.status, "intact");
    assert.equal(verdict.status === "intact" && verdict.head?.seq, 3);
    assert.equal(describeChain(verdict), "chain intact (4 records)");
  });

  test("a hash does not depend on the order in which a record's members are stored", () => {
    const [record] = reread(chainOf([{ b: 2, a: 1 }]));
    const reordered = { chain: (record as any).chain, a: 1, b: 2 };
    assert.equal(verifyChain([reordered]).status, "intact");
  });

  test("a changed record is reported as edited, at its position", () => {
    const records = reread(chainOf(base)) as any[];
    records[2].payload = { injected: true };
    const verdict = verifyChain(records);
    assert.deepEqual([verdict.status, (verdict as any).at, (verdict as any).problem], ["broken", 2, "edited"]);
    assert.match(describeChain(verdict), /CHAIN BROKEN at position 3 of 4: record 2 was changed/);
  });

  test("a removed record is reported where the gap is; so are a swap and a duplicate", () => {
    const removed = reread(chainOf(base));
    removed.splice(1, 1);
    assert.deepEqual([(verifyChain(removed) as any).at, (verifyChain(removed) as any).problem], [1, "out_of_order"]);
    const swapped = reread(chainOf(base));
    [swapped[1], swapped[2]] = [swapped[2], swapped[1]];
    assert.deepEqual([(verifyChain(swapped) as any).at, (verifyChain(swapped) as any).problem], [1, "out_of_order"]);
    const duplicated = reread(chainOf(base));
    duplicated.splice(2, 0, JSON.parse(JSON.stringify(duplicated[1])));
    assert.deepEqual([(verifyChain(duplicated) as any).at, (verifyChain(duplicated) as any).problem], [2, "out_of_order"]);
  });

  test("a record removed from the front is reported: the new first record does not start the chain", () => {
