139	// gen_verify_result_schema.mjs for `nexus verify --json`): one root type and one version constant in one contract
140	// source, written with the `SchemaBuilder` of gen_protocol_schema.mjs, and a ledger keyed by `schema_version`.
141	import fs from "node:fs";
142	import path from "node:path";
