150	/**
151	 * The schema text for `rootType` as `source` (relative to cli/) declares it now, and the value of `versionConst`.
152	 * `script` names the generator in errors; `title(version)` and `description` are the schema's annotations.
153	 */
154	export function generateResultSchema({ script, source, rootType, versionConst, title, description }) {
155	  const api = new API({ cwd: cli });
156	  try {
157	    const snapshot = api.updateSnapshot({ openProjects: [path.join(cli, "tsconfig.json")] });
158	    const project = snapshot.getProjects()[0];
159	    if (!project) throw new Error(`${script}: cli/tsconfig.json did not load as a project`);
160	    const checker = project.checker;
161	    const sourceAt = { document: path.join(cli, source), position: 0 };
162	    const versionSymbol = checker.resolveName(versionConst, SymbolFlags.Value, sourceAt);
163	    const version = versionSymbol && checker.getTypeOfSymbol(versionSymbol)?.value;
164	    if (!Number.isInteger(version)) throw new Error(`${script}: ${versionConst} is not an integer literal in ${source}`);
165	    const rootSymbol = checker.resolveName(rootType, SymbolFlags.TypeAlias, sourceAt);
166	    if (!rootSymbol) throw new Error(`${script}: ${rootType} is not declared in ${source}`);
167	    const root = checker.getDeclaredTypeOfSymbol(rootSymbol);
168	    if (root.isErrorType()) throw new Error(`${script}: ${rootType} did not resolve`);
169	
170	    const builder = new SchemaBuilder(checker);
171	    const rootSchema = builder.schemaOf(root, rootType);
172	    const schema = {
173	      $schema: "https://json-schema.org/draft/2020-12/schema",
174	      title: title(version),
175	      description,
176	      ...rootSchema,
177	      $defs: sortKeys(builder.defs),
178	    };
179	    return { version, text: `${JSON.stringify(schema, null, 2)}\n` };
180	  } finally {
181	    api.close();
182	  }
183	}
