208	      process.exit(1);
209	    }
210	    const problem = ledgerProblem(current, fs.existsSync(ledgerFile) ? JSON.parse(fs.readFileSync(ledgerFile, "utf8")) : [], version);
211	    if (problem) {
212	      console.error(`${ledgerShown}: ${problem}`);
213	      process.exit(1);
214	    }
215	    console.log(`${shown} is current`);
216	  } else {
217	    fs.mkdirSync(path.dirname(file), { recursive: true });
218	    fs.writeFileSync(file, text);
219	    console.log(`wrote ${shown} (sha256 ${sha256(text)})`);
220	  }
221	}
