412	  const error: VerifyJsonError = { schema_version: VERIFY_RESULT_SCHEMA_VERSION, error: "--base x does not name a commit in this repository", exitCode: 2 };
413	  assert.deepEqual(validate(error, schema, schema), []);
414	  assert.ok(validate({ ...error, schema_version: 2 }, schema, schema).length > 0);
415	  assert.ok(validate({ error: "x", exitCode: 2 }, schema, schema).length > 0, "a document without schema_version");
416	  assert.ok(validate({ schema_version: VERIFY_RESULT_SCHEMA_VERSION, verdict: "VERIFIED" }, schema, schema).length > 0, "a result without its required members");
417	});
418	// A small JSON Schema validator for the subset scripts/gen_protocol_schema.mjs emits (draft 2020-12 keywords: type,
419	// const, enum, properties, required, additionalProperties, items, prefixItems, minItems, maxItems, anyOf, oneOf and a
420	// local $ref). It is a test helper, not a general validator: a keyword outside that subset throws, so a generator that
421	// starts emitting a new keyword cannot pass unvalidated.
422	import { isDeepStrictEqual } from "node:util";
423	
424	export type Schema = Record<string, any>;
425	
426	const ANNOTATIONS = new Set(["$schema", "$defs", "title", "description"]);
427	const KEYWORDS = new Set(["$ref", "type", "const", "enum", "properties", "required", "additionalProperties", "items", "prefixItems", "minItems", "maxItems", "anyOf", "oneOf"]);
428	
429	function typeName(value: unknown): string {
430	  if (value === null) return "null";
431	  if (Array.isArray(value)) return "array";
432	  return typeof value;
433	}
434	
435	function resolve(root: Schema, ref: string): Schema {
436	  if (!ref.startsWith("#/")) throw new Error(`unsupported $ref: ${ref}`);
437	  let node: any = root;
438	  for (const part of ref.slice(2).split("/")) node = node?.[part.replace(/~1/g, "/").replace(/~0/g, "~")];
439	  if (!node || typeof node !== "object") throw new Error(`unresolved $ref: ${ref}`);
440	  return node;
441	}
442	
443	/** Every way `value` fails `schema`, as `path: reason` lines; empty when it is valid. `root` resolves `$ref`. */
444	export function validate(value: unknown, schema: Schema, root: Schema = schema, at = "$"): string[] {
445	  for (const keyword of Object.keys(schema)) {
446	    if (!KEYWORDS.has(keyword) && !ANNOTATIONS.has(keyword)) throw new Error(`unsupported schema keyword at ${at}: ${keyword}`);
447	  }
448	  const errors: string[] = [];
449	  if (schema.$ref) errors.push(...validate(value, resolve(root, schema.$ref), root, at));
450	  const actual = typeName(value);
451	  if (schema.type !== undefined && actual !== schema.type) errors.push(`${at}: expected ${schema.type}, got ${actual}`);
452	  if ("const" in schema && !isDeepStrictEqual(value, schema.const)) errors.push(`${at}: expected ${JSON.stringify(schema.const)}`);
453	  if (schema.enum && !schema.enum.some((allowed: unknown) => isDeepStrictEqual(value, allowed))) errors.push(`${at}: not one of ${JSON.stringify(schema.enum)}`);
454	
455	  if (actual === "object") {
456	    const object = value as Record<string, unknown>;
457	    const properties: Record<string, Schema> = schema.properties ?? {};
458	    for (const name of schema.required ?? []) {
459	      if (!Object.hasOwn(object, name)) errors.push(`${at}: missing required ${name}`);
460	    }
461	    for (const [name, member] of Object.entries(object)) {
462	      if (Object.hasOwn(properties, name)) errors.push(...validate(member, properties[name], root, `${at}.${name}`));
463	      else if (schema.additionalProperties === false) errors.push(`${at}: unexpected property ${name}`);
464	      else if (typeof schema.additionalProperties === "object") errors.push(...validate(member, schema.additionalProperties, root, `${at}.${name}`));
465	    }
466	  }
467	
468	  if (actual === "array") {
469	    const array = value as unknown[];
470	    const prefix: Schema[] = schema.prefixItems ?? [];
471	    if (schema.minItems !== undefined && array.length < schema.minItems) errors.push(`${at}: fewer than ${schema.minItems} items`);
472	    if (schema.maxItems !== undefined && array.length > schema.maxItems) errors.push(`${at}: more than ${schema.maxItems} items`);
473	    array.forEach((item, i) => {
474	      if (i < prefix.length) errors.push(...validate(item, prefix[i], root, `${at}[${i}]`));
475	      else if (schema.items) errors.push(...validate(item, schema.items, root, `${at}[${i}]`));
476	    });
477	  }
478	
479	  for (const keyword of ["anyOf", "oneOf"] as const) {
480	    if (!schema[keyword]) continue;
481	    const results: string[][] = schema[keyword].map((option: Schema) => validate(value, option, root, at));
482	    const matches = results.filter((result) => result.length === 0).length;
483	    if (matches === 1 || (matches > 1 && keyword === "anyOf")) continue;
484	    if (matches > 1) {
485	      errors.push(`${at}: matches ${matches} oneOf alternatives`);
486	      continue;
487	    }
488	    // Explain with the alternative that came closest. For a message union that is the variant whose `type` matched;
489	    // when no variant's did, the type is unknown and there is nothing more to say.
490	    const candidates = results.filter((result) => !result.some((error) => error.startsWith(`${at}.type:`)));
491	    const closest = candidates.reduce<string[]>((best, result) => (best.length === 0 || result.length < best.length ? result : best), []);
492	    errors.push(`${at}: matches no ${keyword} alternative`, ...closest);
493	  }
494	  return errors;
495	}
