1	/**
2	 * Hash chain for append-only records (GV-3). Each record carries a link: its position, the hash of the record before
3	 * it, and its own hash over (position, previous hash, canonical content). Changing, removing or reordering a record
4	 * breaks every link after it, so the damage is found by reading the log, without a separate index.
5	 *
6	 * What a chain cannot show by itself: records removed from the END leave a shorter chain that is still consistent.
7	 * A log with a defined last record (a flight's `session_end`) reports whether it is closed; anything stronger needs
8	 * a copy of the head hash kept somewhere else (the signed audit export, GV-2).
9	 *
10	 * This is tamper evidence, not tamper proofing: someone who can rewrite the whole file can recompute every hash.
11	 */
12	import { createHash } from "node:crypto";
13	
14	export interface ChainLink {
15	  /** Position in the log, from 0. */
16	  seq: number;
17	  /** `hash` of the previous record; CHAIN_GENESIS for the first. */
18	  prev: string;
19	  /** SHA-256 over `${seq}\n${prev}\n${canonicalJson(record without its chain)}`, hex. */
20	  hash: string;
21	}
22	
23	export const CHAIN_GENESIS = "0".repeat(64);
24	const HEX64 = /^[0-9a-f]{64}$/;
25	
26	/**
27	 * JSON with object keys sorted at every depth, so a record hashes the same after it has been written and parsed
28	 * again. Follows JSON.stringify for everything else (undefined members dropped, non-finite numbers as null).
29	 */
30	export function canonicalJson(value: unknown): string {
31	  if (value === null || typeof value !== "object") return JSON.stringify(value) ?? "null";
32	  if (Array.isArray(value)) return `[${value.map((item) => (item === undefined ? "null" : canonicalJson(item))).join(",")}]`;
33	  const toJson = (value as { toJSON?: () => unknown }).toJSON;
34	  if (typeof toJson === "function") return canonicalJson(toJson.call(value));
35	  const members: string[] = [];
36	  for (const key of Object.keys(value as Record<string, unknown>).sort()) {
37	    const member = (value as Record<string, unknown>)[key];
38	    if (member === undefined || typeof member === "function" || typeof member === "symbol") continue;
39	    members.push(`${JSON.stringify(key)}:${canonicalJson(member)}`);
40	  }
41	  return `{${members.join(",")}}`;
42	}
43	
44	function linkHash(seq: number, prev: string, content: unknown): string {
45	  return createHash("sha256").update(`${seq}\n${prev}\n${canonicalJson(content)}`, "utf8").digest("hex");
46	}
47	
48	function withoutChain(record: object): Record<string, unknown> {
49	  const { chain: _chain, ...content } = record as Record<string, unknown>;
50	  return content;
51	}
52	
53	/** The record with its link to `previous` (the link of the record before it; undefined for the first). */
54	export function linkRecord<T extends object>(record: T, previous: ChainLink | undefined): T & { chain: ChainLink } {
55	  const seq = previous ? previous.seq + 1 : 0;
56	  const prev = previous ? previous.hash : CHAIN_GENESIS;
57	  return { ...record, chain: { seq, prev, hash: linkHash(seq, prev, withoutChain(record)) } };
58	}
59	
60	export type ChainProblem =
61	  /** The record's content does not match its hash: it was changed after it was written. */
62	  | "edited"
63	  /** The record does not follow the one before it: something was removed, inserted or reordered here. */
64	  | "out_of_order"
65	  /** A record without a link inside a chained log, or a line that is not a record at all. */
66	  | "unlinked";
67	
68	export type ChainVerdict =
69	  /** Every record links to the one before it. `head` is the last link (absent for an empty log). */
70	  | { status: "intact"; records: number; head?: ChainLink }
71	  /** No record carries a link: written before chaining existed. Nothing can be said about its integrity. */
72	  | { status: "unchained"; records: number }
73	  /** The first record that fails, by position in the input. Records before it verified; nothing after it was trusted. */
74	  | { status: "broken"; records: number; at: number; problem: ChainProblem; detail: string };
75	
76	function readLink(record: unknown): ChainLink | undefined {
77	  const chain = record && typeof record === "object" ? (record as { chain?: unknown }).chain : undefined;
78	  if (!chain || typeof chain !== "object") return undefined;
79	  const { seq, prev, hash } = chain as Record<string, unknown>;
80	  if (!Number.isSafeInteger(seq) || (seq as number) < 0 || typeof prev !== "string" || typeof hash !== "string") return undefined;
81	  if (!HEX64.test(prev) || !HEX64.test(hash)) return undefined;
82	  return { seq: seq as number, prev, hash };
83	}
84	
85	function hasChainField(record: unknown): boolean {
86	  return record !== null && typeof record === "object" && Object.prototype.hasOwnProperty.call(record, "chain");
87	}
88	
89	/**
90	 * Check a log read back from disk. `records` are the parsed records in file order; pass `null` for a line that could
91	 * not be parsed, so it is reported at its position instead of being skipped.
92	 */
93	export function verifyChain(records: ReadonlyArray<unknown>): ChainVerdict {
94	  const total = records.length;
95	  if (total === 0) return { status: "intact", records: 0 };
96	  if (records.every((record) => record !== null && readLink(record) === undefined && !hasChainField(record))) {
97	    return { status: "unchained", records: total };
98	  }
99	  let previous: ChainLink | undefined;
100	  for (let at = 0; at < total; at++) {
101	    const record = records[at];
102	    const link = readLink(record);
103	    if (!link) {
104	      const detail = record === null
105	        ? "this line is not a readable record"
106	        : hasChainField(record)
107	          ? "this record has a malformed chain link"
108	          : "this record has no chain link, but the log is chained";
109	      return { status: "broken", records: total, at, problem: "unlinked", detail };
110	    }
111	    const expectedSeq = previous ? previous.seq + 1 : 0;
112	    const expectedPrev = previous ? previous.hash : CHAIN_GENESIS;
113	    if (link.seq !== expectedSeq || link.prev !== expectedPrev) {
114	      const detail = link.seq !== expectedSeq
115	        ? `expected record ${expectedSeq} here, found record ${link.seq}`
116	        : `record ${link.seq} does not follow the record before it`;
117	      return { status: "broken", records: total, at, problem: "out_of_order", detail };
118	    }
119	    if (linkHash(link.seq, link.prev, withoutChain(record as object)) !== link.hash) {
120	      return { status: "broken", records: total, at, problem: "edited", detail: `record ${link.seq} was changed after it was written` };
121	    }
122	    previous = link;
123	  }
124	  return { status: "intact", records: total, head: previous };
125	}
