127	/** One line an operator can read. */
128	export function describeChain(verdict: ChainVerdict): string {
129	  switch (verdict.status) {
130	    case "intact":
131	      return verdict.records === 0 ? "empty" : `chain intact (${verdict.records} record${verdict.records === 1 ? "" : "s"})`;
132	    case "unchained":
133	      return `not chained (${verdict.records} record${verdict.records === 1 ? "" : "s"} written before hash chaining; integrity cannot be checked)`;
134	    case "broken":
135	      return `CHAIN BROKEN at position ${verdict.at + 1} of ${verdict.records}: ${verdict.detail}`;
136	  }
137	}
