185	/**
186	 * The version-decision rule (the same as the protocol ledger's, with the key `schema_version`): the newest ledger entry
187	 * must name the current schema version and the hash of the checked-in schema. Returns what is wrong, or undefined.
188	 */
189	export function resultLedgerProblem(schemaText, ledger, version, versionConst) {
190	  if (!Array.isArray(ledger) || ledger.length === 0) return "the ledger has no entries";
191	  const last = ledger[ledger.length - 1];
192	  if (last.schema_version !== version) return `the newest ledger entry is for schema_version ${last.schema_version}, but ${versionConst} is ${version}`;
193	  const hash = sha256(schemaText);
194	  if (last.schemaSha256 !== hash) return `the newest ledger entry records schema ${last.schemaSha256}, but the schema is ${hash}: add an entry that records the version decision`;
195	  return undefined;
196	}
