  chain: ChainLink;
}

export type AuditChainedLogKind = "flight" | "verification_config_attempts";

/** The log a bundled excerpt was taken from, as it was when the bundle was written. */
export interface AuditChainedLogSource {
  records: number;
  head?: AuditChainHead;
  closed: boolean;
  bytes: number;
  sha256: string;
