      if (log.head !== undefined && !isHead(log.head)) bad(`${at}.head is not { seq, hash }`);
      if (log.status === "intact" && isCount(log.records) && (log.records > 0) !== (log.head !== undefined)) bad(`${at}: an intact log has a head exactly when it has records`);
